/**
 * What a visitor answers before there is an account (onboarding v2, uiux
 * 2026-10-21 spec §10): the language they learn, the one they speak, why,
 * where they meet words, the minutes a day, the reminder time and the
 * optional goal (sales plan G, 23 Oct 2026), and their first word. It is
 * carried through the account sheet to the first card.
 *
 * It has to survive the sheet's sign-up and, on the web, Google's redirect,
 * which leaves the page. So it rides in sessionStorage under one key
 * (`lexpad.introDraft`, the exception the "No data in localStorage" rule in
 * apps/web/CLAUDE.md names): one tab, gone when the tab closes, validated on
 * every read, and read and deleted by the first card (or, for an account
 * that already has notebooks, the gate hands its word to the add sheet
 * once). It replaced `lexpad.introWord` on 2026-10-22, which is cleared on
 * sight so an old tab's word never lingers.
 *
 * Storage can be blocked (a private window with site data refused). The
 * flow still works then: the draft is kept in memory for this page, which
 * covers a password or in-app Google sign-up, and only a full redirect
 * forgets it. Nothing in the draft is sent anywhere before an account
 * exists.
 */
import type { LanguageCode } from '@lexpad/core';
import { MEANING_LANGUAGES, TARGET_LANGUAGES } from '@/features/settings/data.js';

const KEY = 'lexpad.introDraft';
/** The key before onboarding v2, removed whenever the draft is written or cleared. */
const OLD_KEY = 'lexpad.introWord';

/**
 * The longest headword the API takes (`WordCore.headword.maxLength` in
 * contracts/openapi.yaml). Repeated here because the input must stop at it
 * before there is an account to ask; counted in characters, not UTF-16
 * units, so an emoji or a Persian letter is never cut in half.
 */
export const HEADWORD_MAX = 200;

/**
 * What a learner learns for (spec §4.3), in the order the tiles show: the
 * contract's `OnboardingGoal`, which the server checks the answer against.
 */
export const WHY_CHOICES = ['exam', 'work', 'move', 'read', 'travel', 'me'] as const;
export type Why = (typeof WHY_CHOICES)[number];

/**
 * How many reasons one learner may pick (owner, 22 Oct 2026: "let them pick
 * three, not just one"). The contract's `OnboardingAnswers.goals.maxItems`
 * and the server's check say the same; it is a rule of the question, not a
 * tunable, so it lives here beside the choices.
 */
export const MAX_WHY = 3;

/** Where words are met (spec §4.4), in the order the rows show. */
export const WHERE_CHOICES = ['books', 'web', 'video', 'class', 'ai'] as const;
export type Where = (typeof WHERE_CHOICES)[number];

/** The minutes a day the plan offers (spec §4.5, Duolingo's daily goals). */
export const MINUTE_CHOICES = [5, 10, 15, 20] as const;
export type Minutes = (typeof MINUTE_CHOICES)[number];

/**
 * What the learner said to "When should I remind you?" (sales plan G, 23
 * Oct 2026): `on` with the time they kept, `denied` when the phone or the
 * browser refused the permission (remembered, so nothing asks again before
 * the first card), `later` for "Not now". Applied once the account exists
 * (`applyIntroChoices` in `./choices.ts`).
 */
export const REMINDER_ANSWERS = ['on', 'denied', 'later'] as const;
export type ReminderAnswer = (typeof REMINDER_ANSWERS)[number];

export interface IntroReminder {
  /** "HH:mm", the device's local time. */
  time: string;
  answer: ReminderAnswer;
}

/**
 * The optional goal (sales plan G): a number of words by a local date, one
 * of the presets worked out from the plan (`./goal.ts`). Kept on this device
 * only until the server has a field for it.
 */
export interface IntroGoal {
  words: number;
  /** "YYYY-MM-DD", the device's local day. */
  by: string;
}

/** The most words a goal may name: far past any preset, so only a forged value hits it. */
export const GOAL_MAX_WORDS = 10_000;

export interface IntroDraft {
  target?: LanguageCode;
  meaning?: LanguageCode;
  /** Up to MAX_WHY reasons, in the order they were picked: the plan leads with the first. */
  why: Why[];
  /** In the order they were ticked: the plan lists the routes in that order. */
  where: Where[];
  minutes?: Minutes;
  reminder?: IntroReminder;
  goal?: IntroGoal;
  word?: string;
}

/** A change to the draft: an answer, or `undefined` to clear it. */
export type DraftChange = { [K in keyof IntroDraft]?: IntroDraft[K] | undefined };

/** The draft kept for this page when sessionStorage refuses it. */
let memory: IntroDraft | undefined;

/**
 * The word as it will be saved: whitespace at the ends trimmed, any run of
 * spaces or line breaks inside (a pasted sentence) made one space, and cut
 * at the headword limit. A phrase is taken as it is: what the learner wrote
 * down is theirs to keep.
 */
export function normalizeIntroWord(raw: string): string {
  const flat = raw.replace(/\s+/gu, ' ').trim();
  const chars = Array.from(flat);
  return chars.length > HEADWORD_MAX ? chars.slice(0, HEADWORD_MAX).join('').trim() : flat;
}

/** Whether a typed text can become a card: it needs at least one letter in any script. */
export function canBeCard(raw: string): boolean {
  return /\p{L}/u.test(normalizeIntroWord(raw));
}

function isOneOf<T extends string | number>(value: unknown, list: readonly T[]): value is T {
  return (list as readonly unknown[]).includes(value);
}

/** Checks a value read back from storage or history: anything could have written it. */
export function validDraft(value: unknown): IntroDraft {
  const raw = (typeof value === 'object' && value !== null ? value : {}) as Record<string, unknown>;
  const draft: IntroDraft = { why: [], where: [] };
  if (isOneOf(raw.target, TARGET_LANGUAGES)) draft.target = raw.target;
  if (isOneOf(raw.meaning, MEANING_LANGUAGES)) draft.meaning = raw.meaning;
  // A draft written before several reasons could be picked holds one string.
  const reasons: unknown[] = Array.isArray(raw.why) ? raw.why : [raw.why];
  for (const reason of reasons) {
    if (draft.why.length < MAX_WHY && isOneOf(reason, WHY_CHOICES) && !draft.why.includes(reason)) {
      draft.why.push(reason);
    }
  }
  if (Array.isArray(raw.where)) {
    for (const place of raw.where) {
      if (isOneOf(place, WHERE_CHOICES) && !draft.where.includes(place)) draft.where.push(place);
    }
  }
  if (isOneOf(raw.minutes, MINUTE_CHOICES)) draft.minutes = raw.minutes;
  const reminder = validReminder(raw.reminder);
  if (reminder !== undefined) draft.reminder = reminder;
  const goal = validGoal(raw.goal);
  if (goal !== undefined) draft.goal = goal;
  if (typeof raw.word === 'string' && canBeCard(raw.word)) draft.word = normalizeIntroWord(raw.word);
  return draft;
}

/** "HH:mm" on a 24-hour clock, as `<input type="time">` and the settings write it. */
const TIME = /^([01]\d|2[0-3]):[0-5]\d$/u;
/** "YYYY-MM-DD". */
const DAY = /^\d{4}-\d{2}-\d{2}$/u;

function validReminder(value: unknown): IntroReminder | undefined {
  if (typeof value !== 'object' || value === null) return undefined;
  const { time, answer } = value as Record<string, unknown>;
  if (typeof time !== 'string' || !TIME.test(time) || !isOneOf(answer, REMINDER_ANSWERS)) return undefined;
  return { time, answer };
}

function validGoal(value: unknown): IntroGoal | undefined {
  if (typeof value !== 'object' || value === null) return undefined;
  const { words, by } = value as Record<string, unknown>;
  if (typeof words !== 'number' || !Number.isInteger(words) || words < 1 || words > GOAL_MAX_WORDS) {
    return undefined;
  }
  if (typeof by !== 'string' || !DAY.test(by) || Number.isNaN(Date.parse(by))) return undefined;
  return { words, by };
}

function readStored(): unknown {
  try {
    const text = sessionStorage.getItem(KEY);
    return text === null ? undefined : (JSON.parse(text) as unknown);
  } catch {
    return undefined;
  }
}

function write(draft: IntroDraft | undefined): void {
  memory = draft;
  try {
    sessionStorage.removeItem(OLD_KEY);
    if (draft === undefined) sessionStorage.removeItem(KEY);
    else sessionStorage.setItem(KEY, JSON.stringify(draft));
  } catch {
    // Storage blocked: the copy in memory carries it as far as it can.
  }
}

/** The kept draft, checked, without forgetting it. Empty when there is none. */
export function readDraft(): IntroDraft {
  const stored = readStored();
  return validDraft(stored ?? memory);
}

/** Whether anything was answered before the account. */
export function hasDraft(): boolean {
  const draft = readDraft();
  return draft.target !== undefined || draft.word !== undefined;
}

/** Adds answers to the draft. `undefined` in the change clears that answer. */
export function saveDraft(change: DraftChange): IntroDraft {
  const next = validDraft({ ...readDraft(), ...change });
  write(next);
  return next;
}

/** The kept word, if any (the account sheet's chip, the gate's hand-off). */
export function peekDraftWord(): string | undefined {
  return readDraft().word;
}

/** Forgets the draft: the first card has it, or the account already had notebooks. */
export function clearDraft(): void {
  write(undefined);
}

/** A word carried in router state, checked like anything else that arrives from outside. */
export function wordFromState(state: unknown): string | undefined {
  const word = (state as { word?: unknown } | null)?.word;
  return typeof word === 'string' && canBeCard(word) ? normalizeIntroWord(word) : undefined;
}
